      pm.test("ESC-010 responde 403", () => pm.response.to.have.status(403));
      pm.test("ESC-010 cuerpo con la forma exacta del contrato", () => {
        const cuerpo = pm.response.json();
        pm.expect(Object.keys(cuerpo).sort()).to.eql(FORMA);
        pm.expect(cuerpo.citas).to.be.an("array");
        pm.expect(Number.isInteger(cuerpo.tokens)).to.eql(true);
      });
